import numpy as np
from rdkit import Chem
template = Chem.AddHs(Chem.MolFromSmiles(
 "C[C@@H](CC(=O)C[C@H](O)[C@@]1(C)C[C@@H]2OC(=O)C3=C(C(=O)C[C@H]4C(C)(C)C(=O)C=C[C@]34C)[C@@]2(C)[C@]1(C)C(=O)O)C(=O)O"))
with open('xtb.xyz') as f:
    lines = f.read().splitlines()
n=int(lines[0]); syms=[]; X=[]
for l in lines[2:2+n]:
    s,x,y,z=l.split(); syms.append(s); X.append((float(x),float(y),float(z)))
X=np.array(X)
bonded=set()
for b in template.GetBonds():
    i,j=b.GetBeginAtomIdx(),b.GetEndAtomIdx()
    bonded.add((i,j)); bonded.add((j,i))
# also exclude 1-3 pairs
b13=set(bonded)
for b in template.GetBonds():
    i,j=b.GetBeginAtomIdx(),b.GetEndAtomIdx()
    for k,l in list(b13):
        if k==i: b13.add((l,j)); b13.add((j,l))
        if k==j: b13.add((l,i)); b13.add((i,l))
vdw={'C':1.70,'O':1.52,'H':1.20}
clash=[]
for i in range(n):
    for j in range(i+1,n):
        if (i,j) in b13: continue
        d=np.linalg.norm(X[i]-X[j])
        lim=0.75*(vdw[syms[i]]+vdw[syms[j]])
        if d<lim: clash.append((d,syms[i]+str(i),syms[j]+str(j),lim))
print("clashes (<0.75*sumVdW):", len(clash))
for c in sorted(clash)[:10]: print("  %.2f %s %s (lim %.2f)"%c)
EOF
